package par2

import (
	"bytes"
	"context"
	"encoding/binary"
	"os"
	"path/filepath"
	"testing"
)

// These small deterministic fixtures were generated by par2cmdline, not by
// this implementation. Their origin, command and MIT notice are in testdata.
func referenceSet(t *testing.T) ([]Source, *Index) {
	t.Helper()
	var sources []Source
	for _, name := range []string{"realtool.par2", "realtool.vol0+4.par2"} {
		b, err := os.ReadFile(filepath.Join("testdata", name))
		if err != nil {
			t.Fatal(err)
		}
		sources = append(sources, Source{Name: name, Size: int64(len(b)), Reader: bytes.NewReader(b)})
	}
	idx, err := ReadIndex(t.Context(), sources, "fileA.bin", 8000)
	if err != nil {
		t.Fatal(err)
	}
	return sources, idx
}

func TestReferenceRecovery(t *testing.T) {
	for _, missing := range [][]int{{0}, {1, 9}, {0, 4, 8, 13}} {
		t.Run(string(rune('0'+len(missing))), func(t *testing.T) {
			sources, idx := referenceSet(t)
			if idx.SliceSize != 1024 || len(idx.Files) != 2 {
				t.Fatalf("unexpected index: %+v", idx)
			}
			var exponents []uint32
			var rows [][]byte
			for _, ref := range idx.Recovery {
				row, err := ReadRecovery(t.Context(), sources[ref.Source], ref)
				if err != nil {
					t.Fatal(err)
				}
				exponents = append(exponents, ref.Exponent)
				rows = append(rows, row)
			}
			solver, err := NewSolver(idx.SliceSize, exponents, rows, nil)
			if err != nil {
				t.Fatal(err)
			}
			global := 0
			expected := make(map[int][]byte)
			for _, file := range idx.Files {
				data, err := os.ReadFile(filepath.Join("testdata", file.Name))
				if err != nil {
					t.Fatal(err)
				}
				for off := 0; off < len(data); off += idx.SliceSize {
					block := make([]byte, idx.SliceSize)
					copy(block, data[off:min(off+idx.SliceSize, len(data))])
					if !VerifySlice(block, file.Checks[off/idx.SliceSize]) {
						t.Fatal("reference slice checksum mismatch")
					}
					lost := false
					for _, n := range missing {
						lost = lost || n == global
					}
					if lost {
						expected[global] = block
						err = solver.Missing(global)
					} else {
						err = solver.Fold(t.Context(), global, block)
					}
					if err != nil {
						t.Fatal(err)
					}
					global++
				}
			}
			actual, err := solver.Solve(t.Context())
			if err != nil {
				t.Fatal(err)
			}
			for n, want := range expected {
				if !bytes.Equal(actual[n], want) {
					t.Fatalf("recovered slice %d differs from original", n)
				}
			}
		})
	}
}

func TestIndexRejectsWrongIdentityAndCorruption(t *testing.T) {
	sources, idx := referenceSet(t)
	for _, tc := range []struct {
		name string
		size int64
	}{{"other.bin", 8000}, {"fileA.bin", 8001}} {
		if _, err := ReadIndex(t.Context(), sources, tc.name, tc.size); err == nil {
			t.Fatal("accepted wrong target")
		}
	}
	ref := idx.Recovery[0]
	data := make([]byte, sources[ref.Source].Size)
	_, _ = sources[ref.Source].Reader.ReadAt(data, 0)
	data[ref.Offset] ^= 1
	if _, err := ReadRecovery(t.Context(), Source{Size: int64(len(data)), Reader: bytes.NewReader(data)}, ref); err == nil {
		t.Fatal("accepted corrupt parity payload")
	}
	ctx, cancel := context.WithCancel(t.Context())
	cancel()
	if _, err := ReadIndex(ctx, sources, "fileA.bin", 8000); err == nil {
		t.Fatal("ignored cancellation")
	}
}

func TestSolverBoundsAndCancellation(t *testing.T) {
	if _, err := NewSolver(MaxSliceBytes+4, []uint32{0}, [][]byte{{1}}, nil); err == nil {
		t.Fatal("accepted oversized slice")
	}
	s, err := NewSolver(4, []uint32{0}, [][]byte{make([]byte, 4)}, nil)
	if err != nil {
		t.Fatal(err)
	}
	if err := s.Missing(1); err != nil {
		t.Fatal(err)
	}
	if err := s.Missing(2); err == nil {
		t.Fatal("accepted too much damage")
	}
	ctx, cancel := context.WithCancel(t.Context())
	cancel()
	if err := s.Fold(ctx, 0, make([]byte, 4)); err == nil {
		t.Fatal("ignored cancellation")
	}
	if _, err := s.Solve(ctx); err == nil {
		t.Fatal("solve ignored cancellation")
	}
}

func FuzzIndex(f *testing.F) {
	f.Add([]byte("PAR2\x00PKT"))
	for _, name := range []string{"realtool.par2", "realtool.vol0+4.par2"} {
		b, err := os.ReadFile(filepath.Join("testdata", name))
		if err != nil {
			f.Fatal(err)
		}
		f.Add(b)
	}
	for _, length := range []uint64{0, 63, 65, 1 << 63, 1<<64 - 1} {
		b := make([]byte, 64)
		copy(b, magic[:])
		binary.LittleEndian.PutUint64(b[8:], length)
		f.Add(b)
	}
	f.Fuzz(func(t *testing.T, b []byte) {
		if len(b) > 1<<20 {
			t.Skip()
		}
		_, _ = ReadIndex(t.Context(), []Source{{Size: int64(len(b)), Reader: bytes.NewReader(b)}}, "fileA.bin", 8000)
	})
}
